export class PaymentUnavailableError extends Error {
  status: number;
  /** 決済サービスに届いていないと言い切れるときだけ true（接続の拒否など） */
  notCharged: boolean;
  // ...
}

// orders/orderService.ts の catch
if (e instanceof PaymentDeclinedError ||
    (e instanceof PaymentUnavailableError && e.notCharged)) {
  order.status = 'PAYMENT_FAILED';
  await this.#orders.save(order);
}

